// Revisa el pedido antes de gastar llamadas al RPC. Llega del Webhook (en «body») o de «Pedido de prueba».
const b = $input.first().json.body || {};
const errores = [];

// El hash va en minúsculas, como lo devuelve la red: así un mismo pago no se registra dos veces en pagos_fuji
// por llegar una vez con mayúsculas y otra sin.
const txHash = String(b.txHash ?? '').trim().toLowerCase();
if (!/^0x[0-9a-f]{64}$/.test(txHash)) errores.push('txHash tiene que ser el hash de la transacción: 0x y 64 caracteres hexadecimales.');

// Las direcciones se comparan en minúsculas: la misma dirección puede venir con mayúsculas mezcladas.
const destino = String(b.destino ?? '').trim().toLowerCase();
if (!/^0x[0-9a-f]{40}$/.test(destino)) errores.push('destino tiene que ser una dirección de la C-Chain: 0x y 40 caracteres hexadecimales.');

// montoMinimo va en AVAX («0.5» o 0.5) y se pasa a wei como texto, sin la imprecisión de los decimales de JavaScript.
const montoMinimo = String(b.montoMinimo ?? '').trim().replace(',', '.');
let montoMinimoWei = null;
if (/^\d+(\.\d{1,18})?$/.test(montoMinimo)) {
  const [entero, decimales = ''] = montoMinimo.split('.');
  montoMinimoWei = (BigInt(entero) * 10n ** 18n + BigInt(decimales.padEnd(18, '0'))).toString();
} else {
  errores.push('montoMinimo tiene que ser un monto en AVAX, por ejemplo "0.5" (hasta 18 decimales).');
}

const confirmacionesMinimas = Number(b.confirmacionesMinimas ?? 1);
if (!Number.isInteger(confirmacionesMinimas) || confirmacionesMinimas < 0) errores.push('confirmacionesMinimas tiene que ser un número entero, 0 o más.');

return [{ json: { valido: errores.length === 0, errores, txHash, destino, montoMinimo, montoMinimoWei, confirmacionesMinimas } }];

// Aplica las cuatro reglas en orden y responde con la primera que no se cumple.
// Respuesta: { verificado, motivo, detalle }. detalle.regla dice qué regla falló («ninguna» si se cumplen todas).
const pedido = $('Revisar el pedido').first().json;
const tx = $('Leer la transacción').first().json;
const recibo = $('Leer el recibo').first().json;
const ultimo = $('Leer el último bloque').first().json;

function enAVAX(wei) {
  const base = 10n ** 18n;
  const resto = (wei % base).toString().padStart(18, '0').replace(/0+$/, '');
  return resto ? `${wei / base}.${resto}` : `${wei / base}`;
}

const base = {
  hash: pedido.txHash,
  pedido: { destino: pedido.destino, montoMinimo: pedido.montoMinimo, confirmacionesMinimas: pedido.confirmacionesMinimas },
  explorador: `https://build.avax.network/explorer/fuji/c-chain/tx/${pedido.txHash}`,
};
const responder = (verificado, regla, motivo, datos = {}) => [{ json: { verificado, motivo, detalle: { regla, ...base, ...datos } } }];

// 0. ¿Respondió el RPC? Los HTTP Request siguen aunque fallen (Settings → On Error), así siempre hay respuesta.
for (const [que, r] of [['la transacción', tx], ['el recibo', recibo], ['el último bloque', ultimo]]) {
  if (r.error) return responder(false, 'rpc', `No se pudo leer ${que} en Fuji (${r.error.message ?? JSON.stringify(r.error)}). Esperá un momento y volvé a verificar.`);
}

const t = tx.result;
if (!t) return responder(false, 'existe', 'No hay ninguna transacción con ese hash en Fuji. Revisá que esté completo y que sea de Fuji, no de la red principal.');
const r = recibo.result;
if (!r || !t.blockNumber) return responder(false, 'confirmaciones', 'La transacción todavía no entró en un bloque. Esperá unos segundos y volvé a verificar.');

const valor = BigInt(t.value);
const bloque = BigInt(t.blockNumber);
// Ya está en un bloque, así que tiene por lo menos 1 confirmación: el RPC público reparte los pedidos
// entre varios servidores y el «último bloque» a veces llega uno atrasado.
let confirmaciones = BigInt(ultimo.result) - bloque + 1n;
if (confirmaciones < 1n) confirmaciones = 1n;
const datos = {
  de: t.from,
  para: t.to,
  montoAVAX: enAVAX(valor),
  montoWei: valor.toString(),
  bloque: Number(bloque),
  confirmaciones: Number(confirmaciones),
  estado: r.status === '0x1' ? 'exitosa' : 'fallida',
};

// 1. Estado: 0x1 es éxito. Una transacción fallida existe, pero no movió el monto.
if (r.status !== '0x1') return responder(false, 'estado', 'La transacción existe, pero falló (estado 0x0): no movió el monto.', datos);
// 2. Destino: que el pago haya ido a tu dirección y no a otra.
if (String(t.to ?? '').toLowerCase() !== pedido.destino) return responder(false, 'destino', `El pago fue a ${t.to ?? 'la creación de un contrato'} y no a ${pedido.destino}.`, datos);
// 3. Monto: se comparan enteros en wei con BigInt.
if (valor < BigInt(pedido.montoMinimoWei)) return responder(false, 'monto', `El monto (${enAVAX(valor)} AVAX) es menor que el mínimo pedido (${pedido.montoMinimo} AVAX).`, datos);
// 4. Confirmaciones: bloques desde el de la transacción (incluido) hasta el último.
if (confirmaciones < BigInt(pedido.confirmacionesMinimas)) return responder(false, 'confirmaciones', `Tiene ${confirmaciones} confirmaciones y se piden ${pedido.confirmacionesMinimas}. Esperá unos bloques y volvé a verificar.`, datos);

return responder(true, 'ninguna', `Pago verificado: ${enAVAX(valor)} AVAX a ${pedido.destino}, con ${confirmaciones} confirmaciones.`, datos);
